async () => {
  const resp = await fetch(location.href);
  const html = await resp.text();
  // Parse HTML in detached document so SPA can't interfere
  const parser = new DOMParser();
  const doc = parser.parseFromString(html, 'text/html');

  const h1 = doc.querySelector('h1.section-header');
  const location_el = doc.querySelector('.job__location div');
  const applyBtn = doc.querySelector('button[aria-label="Apply"]');
  const links = Array.from(doc.querySelectorAll('.job__description a')).map(a => ({text: a.textContent, href: a.href})).filter(l => /apply/i.test(l.text) || /apply/i.test(l.href));
  const ogUrl = doc.querySelector('meta[property="og:url"]')?.getAttribute('content');
  const description = doc.querySelector('.job__description')?.innerText;

  // Find salary text
  const bodyText = doc.querySelector('.job__description')?.textContent || '';
  const salaryMatch = bodyText.match(/(\$[\d,]+|[\d,]+ USD|[\d,]+ GBP|stipend.*?\.)/i);

  return {
    title: h1?.textContent,
    company: 'Anthropic',
    location: location_el?.textContent,
    applyButtonPresent: !!applyBtn,
    applyLinks: links.slice(0, 3),
    canonicalUrl: ogUrl,
    descriptionLen: description?.length,
    descriptionPreview: description?.substring(0, 800),
    salaryHint: salaryMatch && salaryMatch[0]
  };
}

