input.function:
async () => {
  // Wait briefly for SPA to settle
  await new Promise(r => setTimeout(r, 1500));
  const renderedBody = document.body.innerText.substring(0, 1500);
  const resp = await fetch(location.href);
  const html = await resp.text();
  const parser = new DOMParser();
  const doc = parser.parseFromString(html, 'text/html');
  const title = doc.querySelector('title')?.textContent;
  const ogTitle = doc.querySelector('meta[property="og:title"]')?.getAttribute('content');
  const ogDesc = doc.querySelector('meta[property="og:description"]')?.getAttribute('content');
  const ogUrl = doc.querySelector('meta[property="og:url"]')?.getAttribute('content');
  // Try to find Next.js __NEXT_DATA__ or initial props
  const nextData = doc.querySelector('#__NEXT_DATA__')?.textContent;
  const stateScripts = Array.from(doc.querySelectorAll('script')).filter(s => /jobPosting|posting|initialState|jobBoard/i.test(s.textContent || '')).map(s => s.textContent.substring(0, 500));
  return {
    docTitle: title,
    ogTitle,
    ogDesc,
    ogUrl,
    htmlBytes: html.length,
    renderedBodyChars: document.body.innerText.length,
    renderedBodyPreview: renderedBody,
    hasNextData: !!nextData,
    nextDataPreview: nextData?.substring(0, 1500),
    stateScriptsFound: stateScripts.length,
    firstStateScript: stateScripts[0]
  };
}
